// Testes para fluxos de autenticação com Supabase
const { supabase, createClient } = require('../utils/supabase-client');
const fetch = require('node-fetch');

// Dados para teste
const testUser = {
  email: `user-${Date.now()}@example.com`, // Email único para cada execução
  password: 'Teste@123',
  name: 'Usuário de Teste'
};

// URL base do aplicativo para testes (corresponde à URL do app em ambiente local)
const APP_URL = 'http://localhost:3000';

/**
 * Simula o comportamento do navegador para testar redirecionamentos
 * @param {string} url - URL inicial para fazer a requisição
 * @param {number} maxRedirects - Número máximo de redirecionamentos a seguir
 * @returns {Promise<{finalUrl: string, statusCode: number}>} - URL final após redirecionamentos
 */
async function followRedirects(url, maxRedirects = 5) {
  let currentUrl = url;
  let redirectCount = 0;
  let lastStatusCode = 200;
  
  while (redirectCount < maxRedirects) {
    const response = await fetch(currentUrl, {
      method: 'GET',
      redirect: 'manual', // Não seguir redirecionamentos automaticamente
      headers: {
        'User-Agent': 'Mozilla/5.0 (Node.js Fetch)'
      }
    });
    
    lastStatusCode = response.status;
    
    // Se não for um redirecionamento, retornar a URL atual
    if (![301, 302, 303, 307, 308].includes(response.status)) {
      return { finalUrl: currentUrl, statusCode: lastStatusCode };
    }
    
    // Obter URL do cabeçalho de redirecionamento
    const location = response.headers.get('location');
    if (!location) break;
    
    // Construir URL absoluta se necessário
    currentUrl = location.startsWith('http') 
      ? location 
      : new URL(location, currentUrl).toString();
    
    redirectCount++;
  }
  
  return { finalUrl: currentUrl, statusCode: lastStatusCode };
}

describe('Testes de Fluxos de Autenticação', () => {
  let userId = null;
  
  // Limpar dados de teste após todos os testes
  afterAll(async () => {
    // Remover o usuário de teste se tiver sido criado
    if (userId) {
      // Fazer login como admin ou usar função serverless para remover o usuário
      console.log('Limpando usuário de teste:', userId);
      await supabase.auth.signOut();
    }
  });
  
  test('Deve registrar um novo usuário', async () => {
    // Usar a API do Supabase para registrar um usuário
    const { data, error } = await supabase.auth.signUp({
      email: testUser.email,
      password: testUser.password,
      options: {
        data: {
          full_name: testUser.name,
        }
      }
    });
    
    expect(error).toBeNull();
    expect(data.user).toBeDefined();
    expect(data.user.email).toBe(testUser.email);
    
    // Guardar o ID do usuário para limpeza e testes subsequentes
    userId = data.user.id;
    
    // Verificar se o usuário está confirmado (pode variar dependendo da configuração do Supabase)
    // Nota: em produção pode ser necessário confirmar o email
    expect(data.user.email_confirmed_at).toBeDefined();
  });
  
  test('Deve fazer login com credenciais corretas', async () => {
    // Fazer logout para garantir estado limpo
    await supabase.auth.signOut();
    
    // Fazer login com o usuário registrado
    const { data, error } = await supabase.auth.signInWithPassword({
      email: testUser.email,
      password: testUser.password
    });
    
    expect(error).toBeNull();
    expect(data.user).toBeDefined();
    expect(data.user.id).toBe(userId);
    expect(data.session).toBeDefined();
    expect(data.session.access_token).toBeDefined();
  });
  
  test('Deve rejeitar login com credenciais incorretas', async () => {
    // Fazer logout para garantir estado limpo
    await supabase.auth.signOut();
    
    // Tentar login com senha incorreta
    const { data, error } = await supabase.auth.signInWithPassword({
      email: testUser.email,
      password: 'senha_incorreta'
    });
    
    expect(error).not.toBeNull();
    expect(error.message).toContain('Invalid login credentials');
    expect(data.user).toBeNull();
    expect(data.session).toBeNull();
  });
  
  test('Deve fazer logout corretamente', async () => {
    // Primeiro fazer login
    await supabase.auth.signInWithPassword({
      email: testUser.email,
      password: testUser.password
    });
    
    // Verificar se o login foi bem-sucedido
    const { data: userData } = await supabase.auth.getUser();
    expect(userData.user).toBeDefined();
    
    // Fazer logout
    const { error } = await supabase.auth.signOut();
    expect(error).toBeNull();
    
    // Verificar se o usuário não está mais logado
    const { data: checkData } = await supabase.auth.getUser();
    expect(checkData.user).toBeNull();
  });
  
  // Testes de redirecionamento simulados (em ambiente real, estes seriam testes E2E com Cypress/Playwright)
  
  test('Deve simular redirecionamento após login para página inicial', async () => {
    // Este teste simula o comportamento que ocorreria no frontend
    // Em um teste E2E real, usaríamos Cypress/Playwright para verificar o redirecionamento no browser
    
    // Criamos um novo cliente com as mesmas credenciais do usuário
    const userClient = createClient();
    
    // Login com este cliente
    await userClient.auth.signInWithPassword({
      email: testUser.email,
      password: testUser.password
    });
    
    // Verificamos se temos um token de acesso, que indica login bem-sucedido
    const { data } = await userClient.auth.getSession();
    expect(data.session).toBeDefined();
    expect(data.session.access_token).toBeDefined();
    
    // Na implementação real, após o login o router.push('/') é chamado
    // Aqui simulamos verificando a lógica no AuthProvider.tsx que detectaria o user e redirecionaria
    // Note que este teste é uma aproximação - testes E2E reais testariam o navegador real
    
    // Simulação: Se o usuário está autenticado e tenta acessar /login, será redirecionado para /
    if (data.session) {
      expect(true).toBeTruthy(); // Usuário seria redirecionado para home
    } else {
      expect(false).toBeTruthy(); // Este caso não deveria ocorrer neste teste
    }
  });
  
  test('Deve simular redirecionamento após logout para página de login', async () => {
    // Este teste simula o comportamento que ocorreria no frontend
    const userClient = createClient();
    
    // Primeiro fazer login
    await userClient.auth.signInWithPassword({
      email: testUser.email,
      password: testUser.password
    });
    
    // Fazer logout
    await userClient.auth.signOut();
    
    // Verificar se o usuário está deslogado
    const { data } = await userClient.auth.getSession();
    expect(data.session).toBeNull();
    
    // Na implementação real, o signOut() no AuthProvider.tsx faz router.push('/login')
    // Aqui simulamos esse comportamento
    
    // Simulação: após logout, o usuário seria redirecionado para /login
    if (!data.session) {
      expect(true).toBeTruthy(); // Teste passaria - usuário seria redirecionado para login
    } else {
      expect(false).toBeTruthy(); // Este caso não deveria ocorrer neste teste
    }
  });
  
  test('Deve simular redirecionamento após registro para página de login', async () => {
    // Este teste simula o comportamento que ocorreria no frontend
    // Gerar email único para este teste
    const registerTestUser = {
      email: `register-${Date.now()}@example.com`,
      password: 'Register@123',
      name: 'Registro Teste'
    };
    
    // Usando cliente limpo
    const registerClient = createClient();
    
    // Registrar usuário
    const { data, error } = await registerClient.auth.signUp({
      email: registerTestUser.email,
      password: registerTestUser.password,
      options: {
        data: {
          full_name: registerTestUser.name
        }
      }
    });
    
    expect(error).toBeNull();
    expect(data.user).toBeDefined();
    
    // Na implementação real do RegisterForm.tsx, após registro bem-sucedido
    // ocorre router.push('/registration-success') ou router.push('/login')
    
    // Simulação: após registro, redirecionaria para a página de login ou confirmação
    if (data.user) {
      expect(true).toBeTruthy(); // Teste passa - usuário será redirecionado adequadamente
    } else {
      expect(false).toBeTruthy(); // Esse caso não deveria ocorrer neste teste
    }
  });
});
